import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { getProducts } from "./src/queries" with { type: "ref" };
import { getOrders } from "./src/queries" with { type: "ref" };
import { getAlerts } from "./src/queries" with { type: "ref" };
import { getPurchaseOrders } from "./src/queries" with { type: "ref" };
import { fulfillOrder } from "./src/actions" with { type: "ref" };
import { seedData } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "Warehouse Inventory & Fulfillment Tracker",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getProducts, { entities: ["Product", "Supplier"] }),
    query(getOrders, { entities: ["Order", "OrderItem", "Product"] }),
    query(getAlerts, { entities: ["Alert"] }),
    query(getPurchaseOrders, { entities: ["PurchaseOrder", "Supplier", "Product"] }),
    action(fulfillOrder, { entities: ["Order", "OrderItem", "Product", "Alert", "PurchaseOrder", "Supplier"] }),
  ],
});

import { type GetProducts, type GetOrders, type GetAlerts, type GetPurchaseOrders } from "wasp/server/queries";

export const getProducts: GetProducts<void, any[]> = async (_args, context) => {
  const products = await context.entities.Product.findMany({
    include: {
      supplier: {
        select: {
          name: true,
        },
      },
    },
  });
  return products;
};

export const getOrders: GetOrders<void, any[]> = async (_args, context) => {
  const orders = await context.entities.Order.findMany({
    include: {
      orderItems: {
        include: {
          product: {
            select: {
              sku: true,
              name: true,
            },
          },
        },
      },
    },
  });
  return orders;
};

export const getAlerts: GetAlerts<void, any[]> = async (_args, context) => {
  const alerts = await context.entities.Alert.findMany({
    include: {
      product: {
        select: {
          sku: true,
          name: true,
        },
      },
    },
  });
  return alerts;
};

export const getPurchaseOrders: GetPurchaseOrders<void, any[]> = async (_args, context) => {
  const purchaseOrders = await context.entities.PurchaseOrder.findMany({
    include: {
      supplier: {
        select: {
          name: true,
        },
      },
      product: {
        select: {
          sku: true,
        },
      },
    },
  });
  return purchaseOrders;
};

import { type FulfillOrder } from "wasp/server/actions";
import { prisma } from "wasp/server";

export const fulfillOrder: FulfillOrder<{ orderId: number }, any> = async ({ orderId }, context) => {
  return prisma.$transaction(async (tx) => {
    // 1. Fetch the order with its items
    const order = await tx.order.findUnique({
      where: { id: orderId },
      include: {
        orderItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!order) {
      throw new Error("Order not found");
    }

    if (order.status === "FULFILLED") {
      throw new Error("Order is already fulfilled");
    }

    // 2. Check stock levels for all items
    for (const item of order.orderItems) {
      if (item.product.stock < item.quantity) {
        throw new Error(
          `Insufficient stock for ${item.product.name} (SKU: ${item.product.sku}). ` +
          `Required: ${item.quantity}, Available: ${item.product.stock}`
        );
      }
    }

    // 3. Decrement stock for each product
    for (const item of order.orderItems) {
      await tx.product.update({
        where: { id: item.productId },
        data: {
          stock: {
            decrement: item.quantity,
          },
        },
      });
    }

    // 4. Check low stock thresholds and create alerts / purchase orders
    for (const item of order.orderItems) {
      const updatedProduct = await tx.product.findUnique({
        where: { id: item.productId },
      });

      if (!updatedProduct) continue;

      if (updatedProduct.stock < updatedProduct.lowStockThreshold) {
        // Create low-stock alert
        await tx.alert.create({
          data: {
            productId: updatedProduct.id,
            message: `Low stock alert for ${updatedProduct.name} (SKU: ${updatedProduct.sku}). Current stock: ${updatedProduct.stock}.`,
          },
        });

        // Check if there is already an existing PurchaseOrder for this product with status "SENT"
        const existingPO = await tx.purchaseOrder.findFirst({
          where: {
            productId: updatedProduct.id,
            status: "SENT",
          },
        });

        if (!existingPO) {
          await tx.purchaseOrder.create({
            data: {
              supplierId: updatedProduct.supplierId,
              productId: updatedProduct.id,
              quantity: updatedProduct.reorderQuantity,
              status: "SENT",
            },
          });
        }
      }
    }

    // 5. Set order status to FULFILLED
    await tx.order.update({
      where: { id: orderId },
      data: {
        status: "FULFILLED",
      },
    });

    return { success: true };
  });
};

